from pathlib import Path


def replace_once(path: str, old: str, new: str) -> None:
    file = Path(path)
    text = file.read_text()
    count = text.count(old)
    if count != 1:
        raise SystemExit(f"Expected exactly one marker in {path}, found {count}: {old[:140]!r}")
    file.write_text(text.replace(old, new, 1))


def create_new(path: str, content: str) -> None:
    file = Path(path)
    if file.exists():
        raise SystemExit(f"Refusing to overwrite existing file: {path}")
    file.write_text(content)


create_new(
    "src/application/work-queue-action-input.ts",
    '''export class WorkQueueActionInputValidationError extends Error {\n  public constructor(message: string) {\n    super(message);\n    this.name = "WorkQueueActionInputValidationError";\n  }\n}\n\nexport type ReviewQueueDecision = "accepted" | "changes_requested";\n\nexport interface ReviewQueueActionInput {\n  decision: ReviewQueueDecision;\n  comment?: string;\n}\n\nexport interface ApprovalQueueActionInput {\n  confirmed: true;\n}\n\nexport function parseReviewQueueActionInput(\n  values: URLSearchParams,\n): ReviewQueueActionInput {\n  const decision = values.get("decision");\n  if (decision !== "accepted" && decision !== "changes_requested") {\n    throw new WorkQueueActionInputValidationError(\n      "Choose Accept or Request changes for this review item.",\n    );\n  }\n\n  const rawComment = values.get("comment") ?? "";\n  const comment = rawComment.trim();\n  if (comment.length > 500) {\n    throw new WorkQueueActionInputValidationError(\n      "Review comments must be 500 characters or fewer.",\n    );\n  }\n  if (containsDisallowedControlCharacter(comment)) {\n    throw new WorkQueueActionInputValidationError(\n      "Review comments contain unsupported control characters.",\n    );\n  }\n  if (decision === "changes_requested" && comment.length < 3) {\n    throw new WorkQueueActionInputValidationError(\n      "Requesting changes requires a short review comment.",\n    );\n  }\n\n  return {\n    decision,\n    comment: comment.length > 0 ? comment : undefined,\n  };\n}\n\nexport function parseApprovalQueueActionInput(\n  values: URLSearchParams,\n): ApprovalQueueActionInput {\n  if (values.get("confirmApproval") !== "yes") {\n    throw new WorkQueueActionInputValidationError(\n      "Confirm exact-version approval before continuing.",\n    );\n  }\n  return { confirmed: true };\n}\n\nfunction containsDisallowedControlCharacter(value: string): boolean {\n  return /[\\u0000-\\u0008\\u000B\\u000C\\u000E-\\u001F\\u007F]/u.test(value);\n}\n''',
)

create_new(
    "migrations/0010_current_workflow_action_integrity.sql",
    '''-- Queue-native review and approval actions must target the document's exact current version.\n-- Application services enforce the same invariant; these triggers prevent stale-version evidence\n-- from being inserted through direct SQL or a future alternate adapter.\n\nCREATE TRIGGER reviews_require_current_document_version\nBEFORE INSERT ON reviews\nWHEN NOT EXISTS (\n  SELECT 1\n  FROM workflow_instances workflow\n  JOIN documents document\n    ON document.id = workflow.document_id\n   AND document.tenant_id = workflow.tenant_id\n  WHERE workflow.id = NEW.workflow_instance_id\n    AND workflow.tenant_id = NEW.tenant_id\n    AND workflow.document_version_id = NEW.document_version_id\n    AND document.current_version_id = workflow.document_version_id\n)\nBEGIN\n  SELECT RAISE(ABORT, 'Review evidence must target the document current workflow version.');\nEND;\n\nCREATE TRIGGER approvals_require_current_document_version\nBEFORE INSERT ON approvals\nWHEN NOT EXISTS (\n  SELECT 1\n  FROM workflow_instances workflow\n  JOIN documents document\n    ON document.id = workflow.document_id\n   AND document.tenant_id = workflow.tenant_id\n  WHERE workflow.id = NEW.workflow_instance_id\n    AND workflow.tenant_id = NEW.tenant_id\n    AND workflow.document_id = NEW.document_id\n    AND workflow.document_version_id = NEW.document_version_id\n    AND document.current_version_id = NEW.document_version_id\n)\nBEGIN\n  SELECT RAISE(ABORT, 'Approval evidence must target the document current workflow version.');\nEND;\n''',
)

create_new(
    "tests/unit/work-queue-action-input.test.ts",
    '''import { describe, expect, it } from "vitest";\nimport {\n  parseApprovalQueueActionInput,\n  parseReviewQueueActionInput,\n} from "../../src/application/work-queue-action-input";\n\ndescribe("work queue action input", () => {\n  it("normalizes an accepted review with an optional comment", () => {\n    expect(\n      parseReviewQueueActionInput(\n        new URLSearchParams({\n          decision: "accepted",\n          comment: "  Evidence reviewed.  ",\n        }),\n      ),\n    ).toEqual({ decision: "accepted", comment: "Evidence reviewed." });\n  });\n\n  it("requires a meaningful comment when requesting changes", () => {\n    expect(() =>\n      parseReviewQueueActionInput(\n        new URLSearchParams({ decision: "changes_requested", comment: "  " }),\n      ),\n    ).toThrow(/requires a short review comment/u);\n  });\n\n  it("rejects unsupported decisions and oversized comments", () => {\n    expect(() =>\n      parseReviewQueueActionInput(\n        new URLSearchParams({ decision: "commented", comment: "Note" }),\n      ),\n    ).toThrow(/Choose Accept or Request changes/u);\n    expect(() =>\n      parseReviewQueueActionInput(\n        new URLSearchParams({\n          decision: "accepted",\n          comment: "x".repeat(501),\n        }),\n      ),\n    ).toThrow(/500 characters or fewer/u);\n  });\n\n  it("requires explicit exact-version approval confirmation", () => {\n    expect(parseApprovalQueueActionInput(new URLSearchParams({ confirmApproval: "yes" }))).toEqual({\n      confirmed: true,\n    });\n    expect(() => parseApprovalQueueActionInput(new URLSearchParams())).toThrow(\n      /Confirm exact-version approval/u,\n    );\n  });\n});\n''',
)

create_new(
    "tests/unit/work-queue-action-integrity.test.ts",
    '''import { readFile } from "node:fs/promises";\nimport { DatabaseSync } from "node:sqlite";\nimport { describe, expect, it } from "vitest";\n\nconst timestamp = "2026-08-12T16:30:00.000Z";\nconst hashOne = `sha256:${"1".repeat(64)}`;\nconst hashTwo = `sha256:${"2".repeat(64)}`;\n\nasync function createDatabase(): Promise<DatabaseSync> {\n  const database = new DatabaseSync(":memory:");\n  for (const file of [\n    "0001_initial.sql",\n    "0008_controlled_document_retirement.sql",\n    "0010_current_workflow_action_integrity.sql",\n  ]) {\n    database.exec(\n      await readFile(new URL(`../../migrations/${file}`, import.meta.url), "utf8"),\n    );\n  }\n\n  database.exec(`\n    INSERT INTO identity_subjects (id, display_name, provider, provider_subject, created_at) VALUES\n      ('author-1', 'Avery Author', 'external', 'author-1', '${timestamp}'),\n      ('reviewer-1', 'Riley Reviewer', 'external', 'reviewer-1', '${timestamp}'),\n      ('approver-1', 'Alex Approver', 'external', 'approver-1', '${timestamp}');\n    INSERT INTO tenants (id, name, slug, created_at)\n      VALUES ('tenant-1', 'Tenant One', 'tenant-one', '${timestamp}');\n    INSERT INTO workspaces (id, tenant_id, name, created_at)\n      VALUES ('workspace-1', 'tenant-1', 'Operations', '${timestamp}');\n    INSERT INTO documents\n      (id, tenant_id, workspace_id, title, status, current_version_id, template_provenance, created_at, updated_at)\n      VALUES ('document-1', 'tenant-1', 'workspace-1', 'Checklist', 'in_review', NULL, 'none', '${timestamp}', '${timestamp}');\n    INSERT INTO document_versions\n      (id, tenant_id, document_id, version_number, content_hash, content_provider, content_key, created_by_subject_id, created_at) VALUES\n      ('version-1', 'tenant-1', 'document-1', 1, '${hashOne}', 'r2', 'version-1-key', 'author-1', '${timestamp}'),\n      ('version-2', 'tenant-1', 'document-1', 2, '${hashTwo}', 'r2', 'version-2-key', 'author-1', '${timestamp}');\n    UPDATE documents SET current_version_id = 'version-2' WHERE id = 'document-1';\n    INSERT INTO workflow_definitions (id, tenant_id, name, version, definition_json, created_at)\n      VALUES ('workflow-1', 'tenant-1', 'Review', 1,\n        '{"states":["draft","review","approval","approved"],"transitions":[{"from":"draft","to":"review"},{"from":"review","to":"approval"},{"from":"approval","to":"approved"}]}',\n        '${timestamp}');\n    INSERT INTO workflow_instances\n      (id, tenant_id, document_id, document_version_id, workflow_definition_id, workflow_definition_version, state, created_at, updated_at) VALUES\n      ('instance-v1', 'tenant-1', 'document-1', 'version-1', 'workflow-1', 1, 'review', '${timestamp}', '${timestamp}'),\n      ('instance-v2', 'tenant-1', 'document-1', 'version-2', 'workflow-1', 1, 'review', '${timestamp}', '${timestamp}');\n  `);\n\n  return database;\n}\n\ndescribe("current workflow action integrity migration", () => {\n  it("blocks stale reviews and allows the current workflow version", async () => {\n    const database = await createDatabase();\n    expect(() =>\n      database.exec(`\n        INSERT INTO reviews\n          (id, tenant_id, workflow_instance_id, document_version_id, actor_subject_id, decision, created_at)\n        VALUES ('review-stale', 'tenant-1', 'instance-v1', 'version-1', 'reviewer-1', 'accepted', '${timestamp}');\n      `),\n    ).toThrow(/current workflow version/u);\n\n    expect(() =>\n      database.exec(`\n        INSERT INTO reviews\n          (id, tenant_id, workflow_instance_id, document_version_id, actor_subject_id, decision, created_at)\n        VALUES ('review-current', 'tenant-1', 'instance-v2', 'version-2', 'reviewer-1', 'accepted', '${timestamp}');\n      `),\n    ).not.toThrow();\n  });\n\n  it("blocks stale approvals and allows the current workflow version", async () => {\n    const database = await createDatabase();\n    database.exec("UPDATE workflow_instances SET state = 'approval' WHERE id IN ('instance-v1', 'instance-v2');");\n\n    expect(() =>\n      database.exec(`\n        INSERT INTO approvals\n          (id, tenant_id, document_id, document_version_id, content_hash, actor_subject_id, workflow_instance_id, workflow_definition_id, workflow_definition_version, approved_at)\n        VALUES ('approval-stale', 'tenant-1', 'document-1', 'version-1', '${hashOne}', 'approver-1', 'instance-v1', 'workflow-1', 1, '${timestamp}');\n      `),\n    ).toThrow(/current workflow version/u);\n\n    expect(() =>\n      database.exec(`\n        INSERT INTO approvals\n          (id, tenant_id, document_id, document_version_id, content_hash, actor_subject_id, workflow_instance_id, workflow_definition_id, workflow_definition_version, approved_at)\n        VALUES ('approval-current', 'tenant-1', 'document-1', 'version-2', '${hashTwo}', 'approver-1', 'instance-v2', 'workflow-1', 1, '${timestamp}');\n      `),\n    ).not.toThrow();\n  });\n});\n''',
)

